patch --no-backup-if-mismatch -p1 <<'PATCH'
--- /dev/null
+++ b/build/VerifyFieldDefaults.java
@@ -0,0 +1,20 @@
+import java.lang.reflect.Modifier;
+
+public record VerifyFieldDefaults(String value) {
+    static int counter;
+    static class Nested { int value = 1; }
+    record Empty() {}
+    public static void main(String[] args) throws Exception {
+        int modifiers = Nested.class.getDeclaredField("value").getModifiers();
+        if (Modifier.isPrivate(modifiers) != Boolean.parseBoolean(args[0])) {
+            throw new AssertionError("Wrong access: " + Modifier.toString(modifiers));
+        }
+        if (Modifier.isFinal(modifiers) != Boolean.parseBoolean(args[1])) {
+            throw new AssertionError("Wrong finality: " + Modifier.toString(modifiers));
+        }
+        if (VerifyFieldDefaults.class.getDeclaredField("counter").getModifiers() != Modifier.STATIC) {
+            throw new AssertionError("Static field changed");
+        }
+        System.out.println("Passed private=" + args[0] + ", final=" + args[1]);
+    }
+}
PATCH
